def to_seconds(config):
    """Return the configuration with timeout_ms converted to timeout_s."""
    if "timeout_ms" in config and "timeout_s" in config:
        raise ValueError("Both timeout_ms and timeout_s are present")

    new_config = dict(config)

    if "timeout_ms" in new_config:
        new_config["timeout_s"] = new_config.pop("timeout_ms") / 1000.0

    return new_config
